#!/usr/bin/env python3
"""Unit 28 · Sound, Rhythm and Recorded Music (grades 6–8) — the content source.
Writes ch61–ch64.json and u28_head.json in the SPEC.md shape, then
`python3 assemble.py 28` builds and validates u28.json.

Questions are written right-answer-first; Q() moves the right answer to a
position on a fixed cycle so the answers spread evenly over A–D.
A lesson may carry "try": a link to the bench tool that goes with it
(build_course.py prints it as a button under the reading).

Run from this folder:  python3 u28_src.py && python3 assemble.py 28
"""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))

_k = [0]
ORDER = [1, 3, 0, 2, 2, 0, 3, 1]
def Q(q, right, wrong, why):
    pos = ORDER[_k[0] % len(ORDER)]; _k[0] += 1
    ch = list(wrong); ch.insert(pos, right)
    return {"q": q, "choices": ch, "a": pos, "why": why}

def W(w, d): return {"w": w, "d": d}
def think(title, text, prompt): return {"type": "think", "title": title, "text": text, "prompt": prompt}
def data(title, rows, unit, cite, prompt): return {"type": "data", "title": title, "rows": rows, "unit": unit, "cite": cite, "prompt": prompt}
def source(title, text, cite, prompt, paraphrase=True): return {"type": "source", "title": title, "text": text, "cite": cite, "paraphrase": paraphrase, "prompt": prompt}

DRUMS = {"href": "/drum-machine", "en": "Try it on the Drum Machine", "es": "Pruébalo en la caja de ritmos"}
DECKS = {"href": "/turntables", "en": "Try it on the Turntables", "es": "Pruébalo en los tocadiscos"}
WAVES = {"href": "/waves", "en": "Try it on the Oscilloscope", "es": "Pruébalo en el osciloscopio"}

def L(title, main, reading, words, look, check, tr=None):
    d = {"title": title, "mainIdea": main, "reading": reading, "words": words, "look": look, "check": check}
    if tr: d["try"] = tr
    return d

